return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Urdu','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:37+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ur','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" محفوظ کیا گیا۔','"%1$s" created. %2$d template updated.'=>'"%1$s" تخلیق کیا گیا۔ %2$d سانچے اپ ڈیٹ کیے گئے۔' . "\0" . '"%1$s" تخلیق کیا گیا۔ %2$d سانچے اپ ڈیٹ کیے گئے۔','"%s" created.'=>'"%s" تخلیق کیا گیا۔','%d language not yet linked'=>'%d زبان ابھی تک منسلک نہیں ہے' . "\0" . '%d زبانیں ابھی تک منسلک نہیں ہیں','%d link updated.'=>'%d لنک اپ ڈیٹ کیا گیا۔' . "\0" . '%d لنکس اپ ڈیٹ کیے گئے۔','%d locale pack installed.'=>'%d لوکیل پیک انسٹال ہے۔' . "\0" . '%d لوکیل پیک انسٹال ہیں۔','%d navigation reference updated.'=>'%d نیویگیشن حوالہ اپ ڈیٹ کیا گیا۔' . "\0" . '%d نیویگیشن حوالہ جات اپ ڈیٹ کیے گئے۔','%d part reference updated.'=>'%d حصے کا حوالہ اپ ڈیٹ کیا گیا۔' . "\0" . '%d حصوں کے حوالے اپ ڈیٹ کیے گئے۔','%s Archive'=>'%s آرکائیو','(avg %.1f hits/block)'=>'(اوسط %.1f ہٹس/بلاک)','(avg %.1f hits/entry)'=>'(اوسط %.1f ہٹس/داخلہ)','(disabled)'=>'(غیر فعال)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} میں کوئی قابلِ تبدیل لنک نہیں تھا — مزید جانچ کے لیے دوبارہ اسکین کریں)','.txt file(s) in the directory'=>'.txt فائل(یں) ڈائریکٹری میں','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d مقامی ٹیمپلیٹ(یں) &#8220;%2$s&#8221; تھیم سے محفوظ ہیں لیکن فی الحال غیر فعال ہیں۔ اگر آپ اس تھیم کو دوبارہ فعال کریں گے تو یہ دوبارہ فعال ہو جائیں گے۔ اپنی ترجمہ کو نئے تھیم میں منتقل کرنے کے لیے، انہیں دوبارہ پیدا کریں <strong>سیٹنگز → Lingua Forge → Router → FSE scaffold</strong> کے ذریعے۔','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> خودکار فکس کے قابل لنک','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> لنک جن کا دستی جائزہ لینا ہے','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> پرانی راہ/راہیں','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> ٹیمپلیٹ مسئلہ/مسائل','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'صرف مرتب شدہ .mo فائلیں قبول کی جاتی ہیں۔ فائل کا نام {textdomain}-{locale}.mo کے پیٹرن کی پیروی کرنا چاہیے۔ ایک ہی نام کی فائل اپ لوڈ کرنے سے وہ تبدیل ہو جائے گی۔','Action'=>'عمل','Actions'=>'عمل','active'=>'فعال','Active Languages'=>'فعال زبانیں','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'فعال زبانیں: ہر زبان کو شامل کریں جسے آپ سپورٹ کرنا چاہتے ہیں۔ ہر زبان کو ایک URL پیش لفظ یا سب ڈومین اور ایک hreflang ٹیگ ملتا ہے جو صفحہ کے &lt;head&gt; میں ہوتا ہے۔','Active Provider'=>'فعال فراہم کنندہ','Add entry'=>'داخلہ شامل کریں','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'خاکہ کو بہتر بنانے کے لیے ہدایات شامل کریں — مثلاً اسے مختصر کریں، نتیجہ شامل کریں، زیادہ رسمی انداز استعمال کریں، FAQ بلاک شامل کریں…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'مسودہ بہتر بنانے کے لیے ہدایات شامل کریں — مثلاً، اسے مختصر کریں، نتیجہ کا ایک اختتامی حصہ شامل کریں، زیادہ رسمی انداز استعمال کریں…','Add new entry'=>'نیا داخلہ شامل کریں','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'ایک لائن میں ایک اصطلاح شامل کریں۔ ماخذ اصطلاح اور ہدف کی نمائندگی دونوں ضروری ہیں۔ زبان کا جوڑا تعین کرتا ہے کہ کون سے ترجمہ کے کام اس پابندی پر لاگو ہوتے ہیں۔','Adds a link to the home page so visitors can browse in their language.'=>'ایک لنک شامل کرتا ہے تاکہ زائرین اپنی زبان میں براؤز کر سکیں۔','Administrators only (manage_options)'=>'صرف ایڈمنسٹریٹرز (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'پہلی زبان تبدیل کرنے کے بعد، URL راؤٹنگ کو اپ ڈیٹ کرنے کے لیے پرم لنکس کو فلش کریں (نیچے سیکشن)۔','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL ساخت کی ترتیبات (پاتھ پری فکس ↔ سب ڈومین) تبدیل کرنے کے بعد، ہمیشہ سیٹنگز → پرمالنکس پر جائیں اور ری وائیٹ قوانین کو فلش کرنے کے لیے سیو تبدیلیاں کریں۔','AI Behaviour Preset'=>'AI رویہ پری سیٹ','AI cache cleared. %d entry was removed.'=>'ای اے آئی کیش صاف کر دی گئی۔ %d اندراج ہٹا دی گئی۔' . "\0" . 'ای اے آئی کیش صاف کر دی گئی۔ %d اندراجات ہٹا دی گئی ہیں۔','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI کیش: کیش شدہ AI جوابات کی فہرستیں ہٹ کاؤنٹس کے ساتھ۔ پورے کیش کو یا ایک مخصوص پوسٹ کی انٹریز کو صاف کریں۔ ترجمہ میں تبدیلی سے پہلے "کلئیر" کا استعمال کریں — کیش شدہ نتائج واپس آتے ہیں یہاں تک کہ آپ AI پری سیٹ یا ماڈل کو تبدیل کریں، جب تک کہ کیش انٹری کو نکال نہ دیا جائے۔','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI کی خصوصیات اختیاری ہیں۔ زبان کی رہنمائی، hreflang، زبان سوئچر، اور ترجمہ گروپ سسٹم سب بغیر کسی فراہم کنندہ کے ترتیب کے کام کرتے ہیں۔','AI Limits & Security'=>'AI کی حدیں اور سیکیورٹی','AI provider returned an empty response.'=>'AI فراہم کنندہ نے خالی جواب دیا۔','AI Usage'=>'AI استعمال','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120–160 حروف کا ہدف۔ خالی چھوڑیں تاکہ خلاصہ کا استعمال ہو۔','All time'=>'تمام وقت','Allow editors to lock individual blocks'=>'ایڈیٹرز کو اجازت دیں کہ وہ انفرادی بلاکس کو لاک کریں','Allow Gutenberg template-editing mode on post screens'=>'پوسٹ اسکرین پر Gutenberg ٹیمپلیٹ ایڈیٹنگ موڈ کی اجازت دیں','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'جب پلگ ان ان انسٹال کیا جائے تو زبان کی تفویض، ترجمہ کے تعلقات، میٹا تفصیلات، گلاسری، اور ترجمہ یادداشت بھی حذف کریں۔','Also generate meta description'=>'میٹا تفصیل بھی تیار کریں','Alternative (server-side):'=>'متبادل (سرور-سائیڈ):','An unknown error occurred.'=>'ایک نامعلوم غلطی پیش آئی۔','and'=>'اور','Anthropic (Claude)'=>'انتھروپک (کلود)','any'=>'کچھ بھی','API calls saved by cache'=>'کیش شدہ API کالز','API Key'=>'API کلید','API Keys'=>'API کیز','API Keys Tab'=>'API کیز ٹیب','API Response Cache'=>'API جواب کیش','Applied ✓'=>'درخواست دی گئی ✓','Apply failed — please try again.'=>'درخواست ناکام — براہ کرم دوبارہ کوشش کریں۔','Apply to Block'=>'بلاک پر لاگو کریں','Apply to Editor'=>'ایڈیٹر میں لاگو کریں','Apply to Footnote'=>'حاشیہ پر لاگو کریں','Apply to Meta Description'=>'میٹا تفصیل پر لاگو کریں','Apply translation'=>'ترجمہ لاگو کریں','Applying…'=>'درخواست دی جا رہی ہے…','Approximate size'=>'تقریبی سائز','Archive'=>'آرکائیو','Archive: %s'=>'آرکائیو: %s','Authors and above (edit_published_posts)'=>'مصنفین اور اوپر (edit_published_posts)','Behavior'=>'رویہ','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'رویہ: AI پری سیٹ منتخب کریں (مطلق، متوازن، تخلیقی)، سائٹ بھر میں کسٹم پرامپٹ ہدایات شامل کریں، خودکار پوسٹ سیو ترجمہ کو فعال یا غیر فعال کریں، اور ترجمہ یادداشت کو ترتیب دیں۔','Block Content'=>'بلاک مواد','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'ایک مہذب نوٹس ظاہر کرتا ہے جب موجودہ صفحہ اپنی اصل زبان میں دکھایا جا رہا ہو کیونکہ زائرین کی زبان کے لیے کوئی ترجمہ موجود نہیں ہے۔ یہ Lingua Forge روٹر کے LINGUAFORGE_LANG_FALLBACK_ACTIVE سگنل سے چلتا ہے — جب درخواست کے لوکل کے لیے ترجمہ موجود ہو تو کچھ بھی خارج نہیں ہوتا۔','Block Editor'=>'بلوک ایڈیٹر','block keywordfallback'=>'واپسی','block keywordi18n'=>'آئی18این','block keywordlanguage'=>'زبان','block keywordlinguaforge'=>'لینگوا فورج','block keywordtranslation'=>'ترجمہ','Block locking'=>'بلوک لاک کرنا','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'کسٹم پوسٹ ٹائپز کے لیے رجسٹرڈ بلاک پیٹرنز۔ ترجمہ بٹن کا استعمال کریں تاکہ زبان کا ورژن تیار کیا جا سکے۔ ترجمہ شدہ مواد یہاں محفوظ کیا جاتا ہے اور کسی بھی CPT پوسٹ میں کاپی کیا جا سکتا ہے یا سنیپڈ پیٹرن (ری یوزبل بلاک) کے لیے بطور آغاز استعمال کیا جا سکتا ہے۔','block titleMissing Translation Notice'=>'مفقود ترجمہ نوٹس','Block translation reuses'=>'ترجمہ کی بلاک ری یوز','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'بلاک سطح کی ترجمہ کیش جو پوسٹس کے درمیان مشترک ہے۔ فعال ہونے پر، ایک جیسی بلاکس (ایک جیسا مارک اپ، زبان کا جوڑا، اور گلاسری) کو یادداشت سے فراہم کیا جاتا ہے بجائے اس کے کہ AI کو دوبارہ کال کریں۔ سیٹنگز → رویہ میں ترتیب دیں۔','Browser language redirect'=>'براؤزر زبان ری ڈائریکشن','Built-in preset instructions:'=>'بلٹ ان پری سیٹ ہدایات:','Bulletize (•-prefixed)'=>'بولٹائز کریں (•-پیش شدہ)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'ترجمہ شدہ مساوی کو بلاک سطح پر کیش کریں تاکہ قابل استعمال مواد (مشترکہ فوٹرز، سائیڈبارز، ایکورڈینز، قانونی سیکشنز) ہر بار API کال نہ کریں۔ فعال ہونے پر، ترجمہ کا عمل ہر پوسٹ کو بلاکس میں پارس کرتا ہے، ہر بلاک کو کیش میں دیکھتا ہے، اور صرف ان بلاکس کو AI کو بھیجتا ہے جو کیش میں نہیں ہیں۔ گلاسری میں ترمیم اور تعمیل پری سیٹ میں تبدیلیاں خود بخود متاثرہ کیش شدہ ترجمہ کو منسوخ کرتی ہیں۔ اعداد و شمار دیکھیں اور کیش صاف کریں۔','cached'=>'کیش شدہ','Cached API responses'=>'کیش شدہ API جوابات','Cached block translations'=>'کیش شدہ بلاک ترجمے','Cancel'=>'منسوخ کریں','Cannot determine target language from slug.'=>'ہدف زبان slug سے معلوم نہیں ہو سکی۔','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'سائٹ کی AI استعمال کی حد مقرر کریں اور ان صارف کرداروں کو محدود کریں جو ادائیگی شدہ AI کالز کو چلا سکتے ہیں۔ یہ پہلے سے موجود فی صارف شرح حد (30 درخواستیں / منٹ، ہارڈ کوڈڈ) کے اوپر بیٹھتی ہے جو ایک صارف کے رن وے لوپ سے بچاؤ کرتی ہے۔','chars'=>'حروف','Chunk translated'=>'ٹکڑا ترجمہ شدہ','Chunk translated to:'=>'ٹکڑا ترجمہ ہوا:','Clear'=>'صاف کریں','Clear All'=>'سب کچھ صاف کریں','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'تمام کیش شدہ AI نتائج کو صاف کریں؟ مستقبل کی درخواستیں تازہ API کالز کو متحرک کریں گی جب تک کہ کیش دوبارہ نہ بن جائے۔','Clear API Response Cache'=>'API جواب کیش کو صاف کریں','Clear Debug Files'=>'ڈیبگ فائلیں صاف کریں','Clear hints'=>'اشارے صاف کریں','Clear input'=>'ان پٹ صاف کریں','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'کیا آپ ترجمہ یادداشت کو مکمل طور پر صاف کرنا چاہتے ہیں؟ مستقبل کے ترجمے اسے دوبارہ بنائیں گے۔','Clear Translation Memory'=>'ترجمہ یادداشت صاف کریں','Close'=>'بند کریں','Close language panel'=>'زبان پینل بند کریں','Close popover'=>'پاپ اوور بند کریں','Compliance Preset'=>'مطابقت کا پری سیٹ','Content generated'=>'مواد تیار','Content Generator'=>'مواد پیدا کرنے والا','Content ready'=>'مواد تیار ہے','Contributors and above — default (edit_posts)'=>'شریک کار اور اوپر — ڈیفالٹ (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'کنٹرول کریں کہ مواد کو AI کو کتنا بھیجا جائے اور جواب کتنا بڑا ہو سکتا ہے۔ ایک فیلڈ کو خالی چھوڑیں تاکہ اندرونی ڈیفالٹ استعمال ہو (جیسے پلیس ہولڈر میں دکھایا گیا ہے)۔ اگر بڑی صفحات کاٹ دی جا رہی ہیں تو ان اقدار کو بڑھائیں؛ API کے اخراجات کم کرنے کے لیے انہیں کم کریں۔','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'ای اے آئی مواد پیدا کرنے والے فیچر کے لیے ٹوکن بجٹ اور ان پٹ حدود کو کنٹرول کرتا ہے۔ بلینک فیلڈز کو چھوڑیں تاکہ بلٹ ان ڈیفالٹس استعمال ہوں۔','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'جب ایڈمنسٹریٹر Plugins → Installed Plugins → Delete سے پلگ ان کو حذف کرتا ہے تو یہ کنٹرول کرتا ہے کہ کیا ہوتا ہے۔ پلگ ان کی سیٹنگز اور اے آئی کیش ہمیشہ ہٹائے جاتے ہیں۔ زبان کی تفویض اور ترجمہ کے تعلقات کو بطور ڈیفالٹ رکھا جاتا ہے تاکہ حادثاتی ان انسٹال یا دوبارہ انسٹال پر وہیں سے شروع کیا جا سکے۔','Conversational'=>'بات چیت','Copied ✓'=>'کاپی کیا ✓','Copy'=>'نقل کریں','Copy markup'=>'مارک اپ کاپی کریں','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'نتیجہ کو کاپی کریں اور جہاں ضرورت ہو چپکائیں (مثلاً، براہ راست حاشیہ کے میدان میں)۔','Copy to safe storage'=>'محفوظ اسٹوریج پر کاپی کریں','Could not add entry: source term and target term are required.'=>'داخلہ شامل نہیں کیا جا سکا: ماخذ اصطلاح اور ہدف اصطلاح ضروری ہیں۔','Could not copy the file. Check that the uploads folder is writable.'=>'فائل کو کاپی نہیں کیا جا سکا۔ چیک کریں کہ اپ لوڈز فولڈر قابل تحریر ہے۔','Could not instantiate the provider.'=>'فراہم کنندہ کو شروع نہیں کیا جا سکا۔','Could not save the file. Check that the uploads folder is writable.'=>'فائل کو محفوظ نہیں کیا جا سکا۔ چیک کریں کہ اپ لوڈز فولڈر قابل تحریر ہے۔','Could not save the glossary entry.'=>'مفہومیہ داخلہ محفوظ نہیں کیا جا سکا۔','CPT Block Patterns'=>'CPT بلاک پیٹرنز','Create'=>'بنائیں','Create missing'=>'غائب تخلیق کریں','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'پوسٹ قسم "%s" کے لیے ترجمہ تخلیق کرنے کے لیے ایک فعال انٹیگریشن درکار ہے۔ براہ کرم یقینی بنائیں کہ مطلوبہ انٹیگریشن انسٹال اور فعال ہے۔','Creating…'=>'درست ہو رہا ہے…','Creative / Marketing'=>'تخلیقی / مارکیٹنگ','Creative / Marketing instructions'=>'تخلیقی / مارکیٹنگ ہدایات','Current content (will be overwritten)'=>'موجودہ مواد (اوور رائٹ کیا جائے گا)','Current title'=>'موجودہ عنوان','Current: {current}'=>'موجودہ: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'اس وقت %s مستقل سے وراثت میں ملا ہوا ہے۔ یہاں ایک قیمت منتخب کرنے سے اسے اوور رائیڈ کیا جائے گا۔','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'اس وقت ان پوسٹس کے لیے چھوڑ دیا گیا ہے جو بلاک-تبصرہ خصوصیت کے پلیس ہولڈرز استعمال کرتی ہیں (wp:details خلاصہ فیلڈز، وغیرہ) — یہ موجودہ سنگل-کال ترجمہ راستے سے گرتی ہیں۔','Currently:'=>'اس وقت:','Custom'=>'حسبِ ضرورت','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'روزانہ AI کوٹہ مکمل ہو گیا (%1$d درخواستیں)۔ %2$s UTC پر ری سیٹ ہوتا ہے۔','Daily request limit'=>'روزانہ درخواست کی حد','Debug Files'=>'ڈیبگ فائلیں','Debug files cleared. %d file was removed.'=>'ڈیبگ فائلیں صاف کی گئی۔ %d فائل ہٹا دی گئی۔' . "\0" . 'ڈیبگ فائلیں صاف کی گئی۔ %d فائلیں ہٹا دی گئی ہیں۔','Debug logging'=>'ڈیبگ لاگنگ','Debug logging disabled.'=>'ڈیبگ لاگنگ غیر فعال ہے۔','Debug logging enabled.'=>'ڈیبگ لاگنگ فعال ہے۔','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'ڈیبگ: AI پرامپٹس اور API جوابات کو ایک مقامی فائل میں ریکارڈ کرنے کے لیے ڈیبگ لاگ فعال کریں۔ مسئلہ حل کرنے کے بعد غیر فعال کریں — ڈیبگ موڈ ہر AI درخواست پر ایک فائل لکھتا ہے۔','Delete'=>'حذف کریں','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'کیا آپ ڈیبگ ڈائریکٹری میں تمام .txt فائلیں حذف کرنا چاہتے ہیں؟ خود ڈائریکٹری باقی رہے گی تاکہ مستقبل میں ڈیبگ لکھائی آسانی سے ہو سکے۔ آپ اسے wp-config.php سے بھی فورس کر سکتے ہیں `define( \'LINGUAFORGE_AI_DEBUG\', true );` کے ساتھ جو ٹوگل کو اوور رائیڈ کرتا ہے۔','Delete all files for this override (both .mo and .po)?'=>'اس اوور رائڈ کے لیے تمام فائلیں حذف کریں (دونوں .mo اور .po)؟','Delete content data on uninstall'=>'ان انسٹال پر مواد کا ڈیٹا حذف کریں','Delete this glossary entry?'=>'کیا آپ اس مفہومیہ داخلہ کو حذف کرنا چاہتے ہیں؟','Describe what to write — topic, key points, structure…'=>'بتائیں کہ کیا لکھنا ہے — موضوع، اہم نکات، ساخت…','Directory'=>'ڈائریکٹری','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'پرامپٹ ٹیوننگ کے دوران یا جب آپ کو ہر درخواست AI فراہم کنندہ تک پہنچنی ہو، اس وقت غیر فعال کریں۔ غیر فعال کرنے سے کیش شدہ انٹریز حذف نہیں ہوتی — دوبارہ فعال کرنے سے وہ بحال ہو جاتی ہیں۔ مصروف سائٹس پر فوری API خرچ میں اضافہ متوقع ہے جب یہ غیر فعال ہو۔','Display'=>'ظاہر کریں','Displays the Lingua Forge language switcher.'=>'لینگوا فورج زبان سوئچر دکھاتا ہے۔','Documentation'=>'دستاویزات','Done'=>'ہو گیا','Done — {done} of {total} post(s) fixed.'=>'ہو گیا — {done} میں سے {total} پوسٹیں ٹھیک کی گئیں۔','Down'=>'نیچے','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'ورڈپریس.org سے براہ راست ورڈپریس کور زبان پیک ڈاؤن لوڈ اور انسٹال کریں۔ ایک بار انسٹال ہونے کے بعد، لوکیل URL روٹنگ اور AI ترجمہ ورک فلو کے لیے دستیاب ہو جاتا ہے۔ دستیاب زبانوں کی فہرست ضرورت کے مطابق حاصل کی جاتی ہے — اسے لوڈ کرنے کے لیے نیچے بٹن پر کلک کریں۔','Dropdown direction'=>'ڈراپ ڈاؤن سمت','Editors and above (edit_others_posts)'=>'ایڈیٹرز اور اوپر (edit_others_posts)','Enable API response caching'=>'API جواب کیشنگ فعال کریں','Enable block-level translation cache reuse across posts'=>'پوسٹس کے درمیان بلاک سطح کی ترجمہ کیش کا استعمال فعال کریں','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'کم از کم ایک AI فراہم کنندہ کے لیے اپنی API کلید درج کریں۔ کلیدیں AES-256-GCM کے ساتھ ایک مخصوص سائٹ کے راز (LINGUAFORGE_SECRET) کا استعمال کرتے ہوئے انکرپٹ کی جاتی ہیں۔ بغیر راز کو تبدیل کیے ڈیٹا بیس ایکسپورٹس شیئر نہ کریں۔','environment variable'=>'ماحولیاتی متغیر','Error'=>'خرابی','Expand'=>'وسیع کریں','Expected: {expected}'=>'متوقع: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'اضافی رہنمائی — لہجہ، انداز، پابندیاں، ہدفی سامعین…','Extra guidance — tone, style, constraints…'=>'اضافی رہنمائی — لہجہ، انداز، پابندیاں…','Failed. Please try again.'=>'ناکام۔ براہ کرم دوبارہ کوشش کریں۔','Feature'=>'خصوصیت','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'خصوصیات کو دو سطحوں میں گروپ کیا گیا ہے۔ ہر سطح اور فراہم کنندہ کے لیے بالکل درست ماڈل شناخت کنندہ درج کریں۔ خالی چھوڑیں تاکہ بلٹ ان ڈیفالٹ استعمال کیا جا سکے۔ صرف فعال فراہم کنندہ کے ماڈلز کو رن ٹائم پر کال کیا جاتا ہے — اگر آپ سوئچ کرنے کا ارادہ رکھتے ہیں تو دیگر کو پہلے سے ترتیب دیں۔','File copied to safe storage successfully.'=>'فائل کامیابی سے محفوظ اسٹوریج میں کاپی ہو گئی۔','Files'=>'فائلیں','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'فائلیں نیچے دیے گئے ڈائریکٹری میں آتی ہیں۔ ترجمہ کے مسائل کی تشخیص کے لیے مفید — ایک بار جب آپ کو ضرورت ہو تو بند کریں تاکہ فائلیں جمع نہ ہوں۔ آپ اسے wp-config.php سے بھی فورس کر سکتے ہیں `define( \'LINGUAFORGE_AI_DEBUG\', true );` کے ساتھ جو ٹوگل کو اوور رائیڈ کرتا ہے۔','Filter'=>'فلٹر','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'ڈیبگ آؤٹ پٹ کو غیر عوامی مقام پر ری ڈائریکٹ کرنے کے لیے linguaforge_debug_dir کے ساتھ فلٹر کریں۔','Fix'=>'مرمت کریں','Fix All'=>'سب کو درست کریں','Fix all links'=>'تمام روابط درست کریں','Fix all parts'=>'تمام حصے درست کریں','Fix Links'=>'لنکس کو درست کریں','Fix Nav'=>'نیویگیشن کو درست کریں','Fix Parts'=>'پارٹس کو درست کریں','Fix Template'=>'ٹیمپلیٹ درست کریں','Fixing {n} / {total}…'=>'{n} / {total} کی مرمت جاری ہے…','Fixing…'=>'درست کر رہا ہے…','Flush Permalink Rules'=>'پرم لنک قواعد کو فلش کریں','Flush Permalinks'=>'پرم لنکس کو فلش کریں','Footnote Content'=>'حاشیہ مواد','footnote(s) translated — applied together with content.'=>'حاشیہ جات ترجمہ شدہ — مواد کے ساتھ مل کر لاگو کیا گیا۔','Footnotes'=>'حاشیہ جات','Footnotes payload (advanced)'=>'حاشیہ نوٹس (ایڈوانسڈ)','Forbidden'=>'ممنوع','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php میں LINGUAFORGE_AI_DEBUG مستقل کے ذریعے زبردستی آف۔ اس لائن کو ہٹا کر اس ٹوگل کو یہاں سے کنٹرول کریں۔','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php میں LINGUAFORGE_AI_DEBUG مستقل کے ذریعے زبردستی آن۔ اس لائن کو ہٹا کر اس ٹوگل کو یہاں سے کنٹرول کریں۔','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'پائے گئے {parts} <strong>{total}</strong> میں سے <strong>{scanned}</strong> اسکین شدہ پوسٹ/صفحات کے لیے <strong>{lang}</strong>۔','From'=>'سے','Front Page'=>'فرنٹ پیج','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE لوکلائزیشن: اس ٹیب سے براہ راست فُل سائٹ ایڈیٹنگ ٹیمپلیٹس اور ٹیمپلیٹ پارٹس میں اسکافولڈ، ترجمہ، اور لنکس کی مرمت کریں۔','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'فعال تھیم سے سیڈ شدہ FSE ٹیمپلیٹس۔ اسے بنائیں اور پھر سائٹ ایڈیٹر میں تخصیص کریں۔','Full Article'=>'مکمل مضمون','Full post'=>'مکمل پوسٹ','General'=>'عام','Generate'=>'پیدا کریں','Generate Content'=>'مواد تیار کریں','Generate content…'=>'مواد تیار کریں…','Generate Excerpt'=>'خلاصہ تیار کریں','Generate Meta Description'=>'میٹا تفصیل تیار کریں','Generated Content'=>'تیار کردہ مواد','Generated meta description'=>'تیار کردہ میٹا تفصیل','Generating…'=>'پیدا ہو رہا ہے…','Generation failed.'=>'پیداوار ناکام۔','Getting started'=>'شروع کرنا','Global AI preset'=>'عالمی AI پری سیٹ','Global default (%s)'=>'عالمی ڈیفالٹ (%s)','Glossary'=>'گلاسری','Glossary entry added.'=>'مفہومیہ داخلہ شامل کیا گیا۔','Glossary entry removed.'=>'مفہومیہ داخلہ ہٹا دیا گیا۔','Glossary Tab'=>'گلاسری ٹیب','Google (Gemini)'=>'گوگل (جمینی)','Hide'=>'چھپائیں','Hints'=>'اشارات','Home link text'=>'ہوم لنک کا متن','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'ترجمہ میں یہ کس طرح ظاہر ہونا چاہیے۔ AI کو ہدایت دینے کے لیے ماخذ اصطلاح کے طور پر وہی قدر ٹائپ کریں تاکہ اسے حرف بہ حرف محفوظ رکھا جائے۔','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'آئیکن + لیبل','Icon only'=>'صرف آئیکن','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'اگر چیک کیا گیا، تو پلگ ان ان انسٹال کرنے سے تمام زبان کی تفویض، ترجمہ کے تعلقات، میٹا تفصیلات، صفحات کے پری سیٹ، اے آئی گلاسری، اور ترجمہ یادداشت ہمیشہ کے لیے حذف ہو جائیں گی۔ یہ عمل واپس نہیں لیا جا سکتا۔ جب تک کہ آپ مکمل طور پر ملٹی لنگول سپورٹ کو ہٹا رہے ہوں، اسے ان چیک چھوڑیں۔','Improve writing'=>'تحریر بہتر بنائیں','Informative'=>'معلوماتی','Input tokens'=>'انپٹ ٹوکنز','Install'=>'انسٹال کریں','Install a Language'=>'ایک زبان انسٹال کریں','Installing…'=>'انسٹال ہو رہا ہے…','Instructions (optional)'=>'ہدایات (اختیاری)','Instructions / key points'=>'ہدایات / اہم نکات','Integration API'=>'انٹیگریشن API','Internal Link Fixer'=>'اندرونی لنک مرمت کرنے والا','Introduction only'=>'صرف تعارف','Invalid file reference.'=>'غلط فائل کا حوالہ۔','Invalid filename.'=>'غلط فائل کا نام۔','Invalid language.'=>'غلط زبان۔','Invalid locale code.'=>'غلط لوکیل کوڈ۔','Invalid or primary language.'=>'غلط یا بنیادی زبان۔','Invalid post type.'=>'غلط پوسٹ قسم۔','Invalid template part.'=>'غلط سانچہ حصہ۔','Invalid template type.'=>'غلط سانچہ قسم۔','Key points, ideas, or structure to build from…'=>'اہم نکات، خیالات، یا ساخت جس سے تعمیر کی جائے…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'کیز کو AES-256-CBC کے ساتھ انکرپٹ کیا جاتا ہے قبل اس کے کہ وہ ورڈپریس کے ڈیٹا بیس میں محفوظ ہوں۔ انکرپشن کا راز آپ کے ورڈپریس کے تصدیقی نمک (wp-config.php) سے حاصل کیا جاتا ہے، اس لیے سادہ متن کی کیز کبھی بھی ڈیٹا بیس کو نہیں چھوتی۔','Language'=>'زبان','Language %s installed successfully.'=>'زبان %s کامیابی سے انسٹال ہو گئی ہے۔','Language (optional)'=>'زبان (اختیاری)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'اس سرور پر زبان کی تنصیب غیر فعال ہے (DISALLOW_FILE_MODS سیٹ ہے)۔','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'اس سرور پر زبان کی تنصیب غیر فعال ہے۔ wp-config.php میں DISALLOW_FILE_MODS مستقل سیٹ ہے۔ زبان پیکز کو دستی طور پر WP-CLI کے ذریعے انسٹال کریں: wp language core install de_DE','Language label'=>'زبان کا لیبل','Language Overrides'=>'زبان کی تبدیلی','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'زبان کی اوور رائڈز: لینگوہ فورج UI سٹرنگز کے لیے کسٹم .po/.mo فائلیں منظم کریں۔ اسے پلگ ان فائلوں میں ترمیم کرنے کے بجائے استعمال کریں — اوور رائڈز اپڈیٹس کے دوران برقرار رہتی ہیں۔','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'زبان پیک انسٹالیشن ناکام ہو گئی۔ زبان پہلے سے انسٹال ہو سکتی ہے، لوکیل کوڈ غلط ہو سکتا ہے، یا آپ کا سرور فائل لکھنے سے روک رہا ہے۔','Language Setup'=>'زبان کی سیٹ اپ','Language Switcher'=>'زبان سوئچر','Language switcher'=>'زبان سوئچر','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'تھیم کے زبان مخصوص نقول۔ ایک بار اسکافولڈ ہونے کے بعد، ٹیمپلیٹس زبان مخصوص پارٹ کا حوالہ دینے کے لیے اپ ڈیٹ ہو جاتے ہیں۔','Language:'=>'زبان:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'روٹر کو معلوم زبانیں (انسٹال شدہ ورڈپریس لوکیل پیکز اور بنیادی زبان سے حاصل شدہ)۔ مزید زبانیں دستیاب کرنے کے لیے ذیل کے سیکشن میں اضافی زبان پیکز انسٹال کریں۔','Last 30 days'=>'پچھلے 30 دن','Last 7 days'=>'پچھلے 7 دن','Lead paragraph (≤60 w)'=>'مقدمہ پیراگراف (≤60 الفاظ)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'ایک ماڈل فیلڈ کو خالی چھوڑیں تاکہ اس سطح کے لیے بلٹ ان ڈیفالٹ استعمال ہو۔ پلیس ہولڈر ٹیکسٹ دکھاتا ہے کہ کون سا ماڈل استعمال ہوگا۔','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'برانڈ کے نام اور زبان سے آزاد اصطلاحات کے لیے خالی چھوڑیں جنہیں کسی بھی زبان سے ترجمہ کرنے کے باوجود نافذ کیا جانا چاہیے۔','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'اس داخلہ کو تمام ہدف زبانوں پر لاگو کرنے کے لیے خالی چھوڑیں — برانڈ کے نام، مخففات، اور اصطلاحات کے لیے جو ہر ترجمہ میں حرف بہ حرف محفوظ رہنی چاہئیں۔','Leave blank to keep the existing key. Enter a new value to replace it.'=>'خالی چھوڑیں تاکہ موجودہ کلید کو برقرار رکھا جا سکے۔ اسے بدلنے کے لیے ایک نئی قیمت درج کریں۔','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'خالی چھوڑیں تاکہ بلٹ ان ڈیفالٹ استعمال کیا جا سکے۔ محفوظ شدہ اوور رائیڈ کو صاف کرنے سے اگلی بار ڈیفالٹ بحال ہو جائے گا۔','Legal / Compliance'=>'قانونی / تعمیل','Legal / Compliance instructions'=>'قانونی / تعمیل ہدایات','Light'=>'ہلکا','Light (default — fast and cost-effective)'=>'ہلکا (پہلا — تیز اور کم قیمت)','Light (fast and cost-effective — Haiku / Flash)'=>'ہلکا (تیز اور کم قیمت — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'لائٹ: میٹا تفصیلات اور اقتباس پیدا کرنے کے لیے استعمال ہوتا ہے — تیز، کم قیمت۔','Limit results to pages in the given Lingua Forge language code.'=>'دی گئی لینگو فورج زبان کوڈ میں صفحات کے نتائج محدود کریں۔','Limits'=>'حدیں','Lingua Forge'=>'لینگوا فورج','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'لینگو فورج آپ کی ورڈپریس سائٹ میں کثیر زبان روٹنگ، AI سے چلنے والا ترجمہ، hreflang SEO ٹیگز، اور زبان سوئچر شامل کرتا ہے۔','Lingua Forge AI Tools'=>'لینگوا فورج اے آئی ٹولز','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge دو Gutenberg خصوصیات کو محدود کرتا ہے تاکہ زبانوں کے درمیان اداریہ رویہ مستقل رہے۔ یہاں شامل ہوں جب آپ کو مکمل Gutenberg / FSE صلاحیتوں کی ضرورت ہو۔','Lingua Forge Settings'=>'لینگو فورج سیٹنگز','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'لینگو فورج دو آزاد کیشنگ پرتیں استعمال کرتا ہے تاکہ AI API کالز کو دہرانے سے بچا جا سکے۔ ہر ایک کو دیکھنے اور منظم کرنے کے لیے نیچے ٹیبز استعمال کریں۔','Lingua Forge uses two model tiers per provider:'=>'لینگو فورج ہر فراہم کنندہ کے لیے دو ماڈل سطحیں استعمال کرتا ہے:','Lingua Forge — Quick Translate'=>'لینگوا فورج — فوری ترجمہ','Lingua Forge — Settings'=>'لینگوا فورج — سیٹنگز','link(s)'=>'لنک','Links'=>'لنکس','Load available languages'=>'دستیاب زبانیں لوڈ کریں','Loading…'=>'لوڈ ہو رہا ہے…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'لوکو ترجمہ اپنی مرضی کے ترجمے wp-content/languages/loco/ میں محفوظ کرتا ہے — ایک جگہ جو کہ ایک WP کور اپ ڈیٹ، پلگ ان کی دوبارہ تنصیب، یا اگر لوکو ترجمہ خود کو ہٹا دیا جائے تو خاموشی سے مٹ سکتی ہے۔ یہاں فائلیں کاپی کرنے سے وہ Lingua Forge i18n-overrides ڈائریکٹری میں منتقل ہو جاتی ہیں، جو ان تمام واقعات کے دوران برقرار رہتی ہے اور ہر درخواست پر خود بخود لوڈ ہوتی ہے۔','Loco Translate — Copy to Safe Storage'=>'لوکو ترجمہ — محفوظ اسٹوریج پر کاپی کریں','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'سب سے کم ورڈپریس صلاحیت جو AI خصوصیات کو فعال کرنے کی اجازت دیتی ہے۔ اس کو سخت کرنا ملٹی-مصنف سائٹس پر شریک کار یا آزمائشی اکاؤنٹس کو ادائیگی شدہ AI کالز چلانے سے روکتا ہے۔ فیچر کے مطابق override کریں via the linguaforge_required_capability فلٹر۔','Maintenance'=>'مرمت','Maintenance Tab'=>'مینٹیننس ٹیب','Make casual'=>'غیر رسمی بنائیں','Make concise'=>'مختصر بنائیں','Make formal'=>'رسمی بنائیں','Mark citations needed'=>'حوالہ جات کی ضرورت کو نشان زد کریں','Max context characters'=>'مکمل سیاق و سباق کے کردار زیادہ سے زیادہ','Max hints characters'=>'اشارہ کے کردار زیادہ سے زیادہ','Max input characters'=>'زیادہ سے زیادہ ان پٹ حروف','Max output tokens'=>'زیادہ سے زیادہ آؤٹ پٹ ٹوکن','Maximum characters accepted from the input field. Default: 8 000.'=>'ان پٹ فیلڈ سے قبول شدہ زیادہ سے زیادہ کردار۔ ڈیفالٹ: 8،000۔','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'جب کوئی اشارہ فراہم نہیں کیا جاتا تو ای اے آئی کو پاس کیے گئے موجودہ پوسٹ مواد کے زیادہ سے زیادہ کردار۔ ڈیفالٹ: 6،000۔','Maximum characters read from the Hints field. Default: 2 000.'=>'اشاروں کے میدان سے پڑھنے کے لیے زیادہ سے زیادہ کردار۔ ڈیفالٹ: 2،000۔','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'ای اے آئی کو بھیجے گئے پوسٹ مواد کی زیادہ سے زیادہ تعداد۔ 0 کا مطلب کوئی حد نہیں — مکمل مواد ہمیشہ بھیجا جاتا ہے (تجویز کردہ)۔ ایک غیر صفر قیمت مقرر کریں صرف اگر آپ کے فراہم کنندہ کے پاس سخت سیاق و سباق کی ونڈو ہے۔ جب مواد کاٹ دیا جاتا ہے تو PHP ایرر لاگ میں ایک وارننگ لکھی جاتی ہے۔','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'ایک ترجمہ جواب میں AI زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ اگر ترجمہ خاموشی سے ختم ہو رہا ہے، تو اس قدر کو بڑھائیں۔ ڈیفالٹ: 16,000۔','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'ای اے آئی ہر پیداوار رن پر زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ اگر مکمل مضامین کاٹ رہے ہیں تو اسے بڑھائیں۔ ڈیفالٹ: 8،192۔','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'ای اے آئی ہر جلدی ترجمہ پر زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ ڈیفالٹ: 2،000۔','Meta Description'=>'میٹا تفصیل','Meta Description, Excerpt Generator'=>'میٹا تفصیل، اقتباس جنریٹر','Minimum role'=>'کم از کم کردار','Missing pattern name or language.'=>'پٹرن کا نام یا زبان غائب ہے۔','Mode'=>'طریقہ','Model'=>'ماڈل','Model tier'=>'ماڈل سطح','Models'=>'ماڈلز','Models Tab (General)'=>'ماڈلز ٹیب (عام)} ,{','Most recent cached block'=>'سب سے حالیہ کیش شدہ بلاک','Most recent cached response'=>'سب سے حالیہ کیش شدہ جواب','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'ملٹی لسانی راستہ بندی، SEO میٹا ٹیگز، اور AI مواد کے اوزار ورڈپریس کے لیے۔ زبان کا پتہ لگانے، URL راستہ بندی، hreflang، میٹا تفصیلات، اور AI سے چلنے والی اقتباس، میٹا، اور ترجمہ کی خصوصیات کو یکجا کرتا ہے۔','Name displayed in this language. Leave empty to use the source name.'=>'اس زبان میں دکھایا گیا نام۔ خالی چھوڑیں تاکہ ماخذ کا نام استعمال ہو۔','Navigation'=>'نیویگیشن','Navigation has no content to translate.'=>'نیویگیشن کا کوئی مواد ترجمہ کے لیے موجود نہیں۔','Navigation not found.'=>'نیویگیشن نہیں ملی۔','Navigation posts are translated via the Router tab, not this button.'=>'نیویگیشن پوسٹس راؤٹر ٹیب کے ذریعے ترجمہ کی جاتی ہیں، اس بٹن کے ذریعے نہیں۔','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'نیویگیشن ترجمہ کے لیے ایک فعال AI فراہم کنندہ کی ضرورت ہے۔ API کیز ٹیب میں ایک API کلید ترتیب دیں۔','Navigations'=>'نیویگیشنز','Network error — could not reach the WordPress AJAX endpoint.'=>'نیٹ ورک کی خرابی — ورڈپریس AJAX اینڈپوائنٹ سے رسائی حاصل نہیں ہو سکی۔','No %s version found in this translation group.'=>'اس ترجمہ گروپ میں کوئی %s ورژن نہیں ملا۔','No AI provider configured.'=>'AI فراہم کنندہ ترتیب نہیں دیا گیا۔','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'منتخب ونڈو (%s) میں AI استعمال کا ریکارڈ نہیں ہے۔ اوپر ایک وسیع رینج منتخب کریں۔','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'ابھی تک AI استعمال کا ریکارڈ نہیں ہے۔ جب بھی کوئی ایڈیٹر ترجمہ کرتا ہے، میٹا تفصیل تیار کرتا ہے، یا کوئی اور AI خصوصیت استعمال کرتا ہے، تو کل یہاں ظاہر ہوں گے۔','No API key configured for this provider.'=>'اس فراہم کنندہ کے لیے کوئی API کلید ترتیب نہیں دی گئی۔','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'کوئی بلٹ ان ہدایات نہیں — ہر AI فیچر اپنی مخصوص ڈیفالٹس استعمال کرتا ہے۔ اپنی سائٹ کے قواعد شامل کرنے کے لیے نیچے دیے گئے کسٹم پرامپٹ ہدایات کے فیلڈ کو پُر کریں۔','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'ابھی تک کوئی کسٹم لوکو ترجمہ فائلیں نہیں ملی ہیں۔ یہ یہاں ظاہر ہوتی ہیں جب آپ لوکو ترجمہ میں ترجمہ محفوظ کرتے ہیں۔','No file was selected.'=>'کوئی فائل منتخب نہیں کی گئی۔','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'موجودہ فلٹر سے کوئی مفہومیہ داخلہ مطابقت نہیں رکھتا۔ تمام داخلوں کو دیکھنے کے لیے فلٹر صاف کریں، یا نیچے ایک نیا داخلہ شامل کریں۔','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'ابھی تک کوئی مفہومیہ داخلہ نہیں ہے۔ ترجمہ میں اصطلاحات کے نفاذ کے لیے نیچے ایک شامل کریں۔','No internal links found to update.'=>'اپ ڈیٹ کرنے کے لیے کوئی داخلی روابط نہیں ملے۔','No language-specific template parts found to map.'=>'زبان سے مخصوص سانچہ کے حصے نہیں ملے۔','No navigation references needed updating.'=>'نیویگیشن کے حوالے کی ضرورت نہیں۔','No override files uploaded yet.'=>'ابھی تک کوئی اوور رائڈ فائل اپ لوڈ نہیں کی گئی۔','No response from provider — check the error log for details.'=>'پرووائیڈر سے جواب موصول نہیں ہوا — تفصیلات کے لیے ایرر لاگ چیک کریں۔','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'کوئی ثانوی زبانیں ترتیب نہیں دی گئی ہیں۔ اوپر ایک زبان پیک انسٹال کریں تاکہ ٹیمپلیٹ اسکیفولڈنگ فعال ہو سکے۔','No source content found to translate.'=>'کوئی ماخذ مواد ترجمہ کے لیے نہیں ملا۔','No source page linked yet.'=>'ابھی تک کوئی ماخذ صفحہ منسلک نہیں ہے۔','No template part references needed updating.'=>'سانچہ کے حصے کے حوالے کی ضرورت نہیں۔','No {lang} translation registered (TRID missing)'=>'کوئی {lang} ترجمہ رجسٹرڈ نہیں ہے (TRID غائب ہے)','Notes'=>'نوٹس','Notice message'=>'نوٹس پیغام','Notice settings'=>'نوٹس سیٹنگز','Oldest cached block'=>'سب سے پرانا کیش شدہ بلاک','Oldest cached response'=>'سب سے پرانا کیش شدہ جواب','Only .mo files are accepted.'=>'صرف .mo فائلیں قبول کی جاتی ہیں۔','OpenAI (GPT)'=>'اوپن اے آئی (جی پی ٹی)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'ایڈیٹرز کے لیے اختیاری سیاق و سباق (مثلاً "ASIC = ایپلیکیشن-خصوصی انٹیگریٹڈ سرکٹ؛ تکنیکی سیاق و سباق میں انگریزی میں محفوظ رکھیں").','Output'=>'نتیجہ','Output tokens'=>'آؤٹ پٹ ٹوکنز','overridden'=>'اوور رائیڈ کیا گیا','Override file deleted.'=>'اوور رائڈ فائل حذف کر دی گئی۔','Override file uploaded successfully.'=>'اوور رائڈ فائل کامیابی سے اپ لوڈ ہوئی۔','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'اس صفحہ پر ترجمہ اور مواد کی تخلیق کے لیے AI پری سیٹ کو اووررائیڈ کرتا ہے۔ دیگر تمام خصوصیات ہمیشہ عالمی پری سیٹ استعمال کرتی ہیں۔','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'اس صفحہ پر ترجمہ اور مواد کی تخلیق کے لیے AI پری سیٹ کو اووررائیڈ کرتا ہے۔ سائٹ بھر میں حسبِ ضرورت پرامپٹ ہدایات (سیٹنگز → رویہ) ہر درخواست کے ساتھ شامل کی جاتی ہیں، چاہے اس انتخاب سے کوئی فرق نہ پڑے۔','Overview'=>'جائزہ','Page'=>'صفحہ','Part'=>'پارٹ','Paste a footnote, sentence, or any snippet here…'=>'یہاں ایک نوٹ، جملہ، یا کوئی بھی ٹکڑا چسپاں کریں…','Paste text, or select text in the editor first…'=>'متن چسپاں کریں، یا پہلے ایڈیٹر میں متن منتخب کریں…','Paste text, or select text on the page first…'=>'متن چسپاں کریں، یا پہلے صفحہ پر متن منتخب کریں…','Paste your API key…'=>'اپنی API کلید چسپاں کریں…','Path prefix — example.com/de/'=>'پاتھ پری فکس — example.com/de/','Pattern'=>'پیٹرن','Pattern has no content to translate.'=>'پٹرن کا مواد ترجمہ کے لیے نہیں ہے۔','Pattern not found.'=>'پٹرن نہیں ملا۔','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'پٹرن ترجمہ کیا گیا اور محفوظ کیا گیا۔ مواد کو اپنے CPT پوسٹ میں کاپی کریں یا اسے ری یوز ایبل بلاک کے لیے شروع کرنے کے طور پر استعمال کریں۔','Pattern translation failed.'=>'پیٹرن کا ترجمہ ناکام رہا۔','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'AI تیار کردہ ترجمہ، میٹا تفصیلات، اقتباسات، اور مواد کے لیے ہر پوسٹ کے لیے کیش۔ ہمیشہ فعال — کسی علیحدہ ٹوگل کی ضرورت نہیں۔ جب مواد یا AI فراہم کنندہ/ماڈل تبدیل ہوتا ہے تو انٹریز خود بخود منسوخ ہو جاتی ہیں۔ فورس کرنے کے لیے ٹول بار کے "↺ دوبارہ ترجمہ" بٹن استعمال کریں یا نیچے کلئیر پر کلک کریں۔','Permalink rules flushed successfully.'=>'پرم لنک قواعد کامیابی سے فلش ہو گئے۔','Permission denied.'=>'اجازت نامہ مسترد۔','Persuasive'=>'قائل','PHP constant'=>'PHP مستقل','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'اصطلاحات کو پن کریں جن کا ترجمہ نہیں ہونا چاہیے یا جنہیں مخصوص طریقے سے پیش کرنا چاہیے (مثلاً برانڈ نام، مصنوعات کے نام، مخفف)۔ گلاسری پابندیاں ہر AI ترجمہ درخواست میں شامل کی جاتی ہیں: پوسٹ ترجمہ، میٹا تفصیل، اقتباس، اور FSE ٹیمپلیٹ ترجمہ۔','Plain language'=>'سادہ زبان','Please enter some instructions first…'=>'براہ کرم پہلے کچھ ہدایات درج کریں…','Please enter some text first…'=>'براہ کرم پہلے کچھ متن درج کریں…','Post'=>'پوسٹ','Post not found.'=>'پوسٹ نہیں ملی۔','Post Types'=>'پوسٹ ٹائپز','Prefilled from excerpt. Edit to override.'=>'خلاصہ سے پہلے سے بھرا ہوا۔ اوور رائیڈ کرنے کے لیے ترمیم کریں۔','Primary Language'=>'پہلی زبان','Primary language'=>'پہلی زبان','Primary language saved.'=>'پہلی زبان محفوظ کی گئی۔','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'اصلی زبان: وہ زبان جس میں آپ کا موجودہ مواد لکھا گیا ہے۔ تمام ترجمے اسی زبان سے تیار کیے جاتے ہیں؛ اسے تبدیل کرنے سے کوئی پوسٹ منتقل یا حذف نہیں ہوتی۔','Processing…'=>'پروسیس ہو رہا ہے…','Provider'=>'فراہم کنندہ','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'فراہم کنندہ نے کوئی متن واپس نہیں کیا۔ تفصیلی ناکامی کی وجہ کے لیے ورڈپریس کی غلطی لاگ چیک کریں۔','Quality'=>'معیار','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'معیار (ڈیفالٹ — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'معیار (سونٹ / GPT-4o / جیمینی پرو)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'معیار: پوسٹ ترجمہ اور مواد پیدا کرنے کے لیے استعمال ہوتا ہے — اعلیٰ معیار، زیادہ قیمت۔','Quick Translate'=>'جلدی ترجمہ','Quick Translation'=>'جلدی ترجمہ','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'جلدی ترجمہ کو اسنپٹ/چنک موڈ کے لیے استعمال کیا جاتا ہے — شارٹ پیغامات کو ٹول بار، ایڈیٹر، یا بلاک پاپ اوور سے مطالبہ پر ترجمہ کیا جاتا ہے۔ یہ مکمل صفحہ ترجمہ سے ایک علیحدہ، ہلکی سی ترتیب استعمال کرتا ہے تاکہ جواب تیز اور کم قیمت رہیں۔','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'s canLockBlocks کو دوبارہ فعال کرتا ہے۔ یہ اداریہ ٹیمپلیٹس کے لیے مفید ہے جنہیں مخصوص بلاکس کو حرکت دینے یا حذف کرنے سے روکنا ہوتا ہے۔','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode کو دوبارہ فعال کرتا ہے۔ یہ مکمل سائٹ ایڈیٹنگ ورک فلو کے لیے بنیادی ہے جہاں پوسٹ سطح کے ٹیمپلیٹ اوور رائیڈز ارادتا ہوتے ہیں۔','Re-generates and updates the cached result.'=>'کیش شدہ نتیجہ کو دوبارہ پیدا اور اپ ڈیٹ کرتا ہے۔','Re-scan'=>'دوبارہ اسکین کریں','Re-scanning…'=>'دوبارہ اسکین کر رہے ہیں…','Re-translate'=>'دوبارہ ترجمہ کریں','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'براؤزر کے Accept-Language ہیڈر کی بنیاد پر زائرین کو ان کی ترجیحی زبان پر ری ڈائریکٹ کریں','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'مزید بہتر بنائیں — مثلاً "اسے مختصر کریں" یا "رسمی انداز استعمال کریں"…','Refine further:'=>'مزید بہتر بنائیں:','Refinement'=>'ترقی','Refinement failed — please try again.'=>'ترقی میں ناکامی — براہ کرم دوبارہ کوشش کریں۔','Refining…'=>'ترقی پذیر…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'ورڈپریس کے ری رائٹ قواعد کو دوبارہ پیدا کرتا ہے تاکہ URL پری فکسز، زبان مخصوص سلگ، اور آرکائیو ری رائٹس سب ہم آہنگ ہوں۔ بنیادی زبان تبدیل کرنے یا نئی زبان کی حمایت شامل کرنے کے بعد ضروری ہے۔','Remove stored key'=>'محفوظ شدہ کلید کو ہٹائیں','Report an issue on GitHub'=>'گٹ ہب پر مسئلہ رپورٹ کریں','Request failed — please try again.'=>'درخواست ناکام — براہ کرم دوبارہ کوشش کریں۔','Request failed.'=>'درخواست ناکام۔','Request failed. Check your connection.'=>'درخواست ناکام۔ اپنی کنکشن چیک کریں۔','Request failed. Please try again.'=>'درخواست ناکام۔ براہ کرم دوبارہ کوشش کریں۔','Requests'=>'درخواستیں','Reset'=>'ری سیٹ','Result will appear here…'=>'نتیجہ یہاں ظاہر ہوگا…','Retranslate'=>'دوبارہ ترجمہ کریں','Retranslating…'=>'دوبارہ ترجمہ ہو رہا ہے…','Review carefully — links and slugs not updated.'=>'احتیاط سے جائزہ لیں — روابط اور سلگ اپ ڈیٹ نہیں ہوئے۔','Review translation before applying'=>'درخواست سے پہلے ترجمہ کا جائزہ لیں','Revise'=>'دوبارہ جائزہ لیں','Revision'=>'نظر ثانی','Revision Type'=>'نظر ثانی کی قسم','Router'=>'روٹر','Router Tab'=>'روٹر ٹیب','Save Debug Setting'=>'ڈیبگ سیٹنگ محفوظ کریں','Save Router Settings'=>'روٹر سیٹنگز محفوظ کریں','Save Settings'=>'سیٹنگز محفوظ کریں','Save the post to persist changes.'=>'تبدیلیاں محفوظ کرنے کے لیے پوسٹ کو محفوظ کریں۔','Save Uninstall Setting'=>'ان انسٹال سیٹنگ محفوظ کریں','Saved to the meta description field when you apply.'=>'جب آپ درخواست دیں گے تو یہ فیلڈ میں محفوظ ہو جائے گا۔','Scan failed: '=>'اسکین ناکام: ','Scan request failed. Please try again.'=>'اسکین کی درخواست ناکام ہو گئی۔ براہ کرم دوبارہ کوشش کریں۔','Scanning posts for broken language links…'=>'ٹوٹے ہوئے زبان کے لنکس کے لیے پوسٹس اسکین کر رہے ہیں…','Search'=>'تلاش','Search Results'=>'تلاش کے نتائج','Security check failed — file path is not permitted.'=>'سیکیورٹی چیک ناکام — فائل کا راستہ اجازت یافتہ نہیں ہے۔','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'اس زبان کا انتخاب کریں تاکہ اس کے FSE ٹیمپلیٹس، ٹیمپلیٹ پارٹس، اور نیویگیشن مینو کو منظم کیا جا سکے۔','Select language'=>'زبان منتخب کریں','SEO character-count info'=>'SEO حروف کی گنتی کی معلومات','Server setup (subdomain)'=>'سرور سیٹ اپ (سب ڈومین)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'یہ سائٹ بھر میں تمام خصوصیات کے لیے ڈیفالٹ AI رویہ مقرر کرتا ہے۔ انفرادی پوسٹس اس کو ترجمانی اور مواد تخلیق کے لیے اوور رائیڈ کر سکتی ہیں، جو کہ Lingua Forge میٹا باکس کے ذریعے ہے۔','Settings'=>'سیٹنگز','Settings saved.'=>'سیٹنگز محفوظ ہو گئی ہیں۔','Show home link'=>'ہوم لنک دکھائیں','Shown when no translation exists for the visitor\'s language.'=>'جب کوئی ترجمہ موجود نہ ہو تو ظاہر ہوتا ہے۔','Single'=>'سنگل','Single %s'=>'سنگل %s','Single: %s'=>'سنگل: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC دن کے لیے سائٹ بھر میں AI درخواستوں کی چھت (یہ دونوں ٹولبار ترجمے اور بلاک ترمیمات کو شمار کرتا ہے)۔ کاؤنٹر UTC آدھی رات کو ری سیٹ ہوتا ہے۔ اسے 0 پر سیٹ کریں تاکہ حد کو غیر فعال کیا جا سکے۔','Size'=>'سائز','Some link fixes failed.'=>'کچھ روابط کی درستگی ناکام رہی۔','Some nav ref fixes failed.'=>'کچھ نیویگیشن ریفرنسز کی درستگی ناکام رہی۔','Some part fixes failed.'=>'کچھ حصوں کی درستگی ناکام رہی۔','Some parts could not be created.'=>'کچھ حصے نہیں بن سکے۔','Some templates could not be created.'=>'کچھ ٹیمپلیٹس نہیں بن سکے۔','Some translations failed.'=>'کچھ ترجمے ناکام رہے۔','Source file not found.'=>'ماخذ فائل نہیں ملی۔','Source lang'=>'ماخذ زبان','Source language'=>'ماخذ زبان','Source term'=>'ماخذ اصطلاح','Standard'=>'معیاری','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'معیاری ہر خصوصیت کے اپنے مخصوص درجہ حرارت کا استعمال کرتا ہے: ترجمہ T=0.2 (مستحکم)، فوری ترجمہ T=0.4، مواد تخلیق T=0.6 (تخلیقی)۔ دیگر پری سیٹس تمام خصوصیات پر ایک مقررہ درجہ حرارت لاگو کرتی ہیں۔','Status'=>'حالت','Status / Actions'=>'حالت / عمل','Storytelling'=>'کہانی سنانا','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'قانونی، ریگولیٹری، طبی، یا تکنیکی مواد کے لیے سخت تحفظ کا موڈ۔ جب فعال ہو، ہر AI خصوصیت کم سیمپلنگ درجہ حرارت استعمال کرتی ہے اور اپنے نظام پرامپٹ کے نیچے اضافی متن شامل کرتی ہے — اصطلاحات، آرٹیکل نمبرز، یونٹس، برانڈ نام، اور ریگولیٹری زبان کو حرف بہ حرف محفوظ رکھا جاتا ہے، نہ کہ پیرا فریز کیا جاتا ہے۔','Structured Outline'=>'ساختی خاکہ','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'ذیلی ڈومین موڈ آپ کے ویب سرور کو تمام زبان کے ذیلی ڈومینز (مثلاً de.example.com) کو اس ورڈپریس تنصیب کی طرف اشارہ کرنے کی ضرورت ہے۔ موڈ تبدیل کرنے کے بعد، permalink قواعد کو فلش کریں اور کسی بھی کیش کو صاف کریں۔ اگر آپ کا ہوم یو آر ایل www شامل ہے (مثلاً www.example.com)، تو lf_base_domain فلٹر کا استعمال کریں تاکہ صرف بنیادی ڈومین سیٹ کیا جا سکے تاکہ ذیلی ڈومینز صحیح طریقے سے بنیں۔','Subdomain — de.example.com/'=>'ذیلی ڈومین — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'موجودہ فراہم کنندگان: انتھروپک (کلود), اوپن اے آئی (GPT), گوگل (جمینی)۔ صرف ایک فراہم کنندہ فعال ہوتا ہے۔ فعال فراہم کنندہ کو جنرل ٹیب پر منتخب کریں۔','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، فی خصوصیت','Target lang'=>'ہدف زبان','Target Language'=>'ہدف زبان','Target language'=>'ہدف زبان','Target term'=>'ہدف اصطلاح','Target: 140–160 chars for optimal SERP display'=>'ہدف: 140–160 حروف مثالی SERP نمائش کے لیے','Technical'=>'تکنیکی','Technical / Scientific'=>'تکنیکی / سائنسی','Technical / Scientific instructions'=>'تکنیکی / سائنسی ہدایات','Template "%s" already exists.'=>'سانچہ "%s" پہلے سے موجود ہے۔','Template "{expected}" does not exist — create it in the Site Editor first.'=>'ٹیمپلیٹ "{expected}" موجود نہیں — پہلے اسے سائٹ ایڈیٹر میں بنائیں۔','Template has no content.'=>'سانچہ کا مواد نہیں ہے۔','Template mode'=>'ٹیمپلیٹ موڈ','Template not found or not stored in the database.'=>'سانچہ نہیں ملا یا ڈیٹا بیس میں محفوظ نہیں۔','Template part "%s" already exists.'=>'سانچہ حصہ "%s" پہلے سے موجود ہے۔','Template part has no content.'=>'سانچہ کا حصہ کا مواد نہیں ہے۔','Template part not found or not stored in the database.'=>'سانچہ کا حصہ نہیں ملا یا ڈیٹا بیس میں محفوظ نہیں۔','Template Parts'=>'ٹیمپلیٹ پارٹس','Templates'=>'ٹیمپلیٹس','Test connection'=>'کنکشن کا ٹیسٹ کریں','Testing…'=>'آزمائش جاری ہے…','Text domain / locale'=>'ٹیکسٹ ڈومین / لوکیل','Text to translate'=>'ترجمہ کے لیے متن','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'API جواب کیش ہر AI درخواست کا خام نتیجہ اسٹور کرتا ہے — ترجمہ، میٹا تفصیل، اقتباس، اور مواد پیداوار — ان پٹ کا ہیش کے ذریعے کی جاتی ہے (مواد، زبان کا جوڑا، فراہم کنندہ، ماڈل)۔ ایک جیسی ان پٹ کے ساتھ بعد کی درخواستیں کیش سے فراہم کی جاتی ہیں بغیر API کال کے۔ یہ کیش ترجمہ یادداشت سے مختلف ہے: ترجمہ یادداشت بلاک سطح پر کام کرتی ہے اور پوسٹس کے درمیان مشترک ہے؛ API جواب کیش فیچر سطح پر کام کرتا ہے اور ہر پوسٹ کے لیے کیڈ ہے۔','The editor did not accept the content — please try again.'=>'مدیر نے مواد کو قبول نہیں کیا — براہ کرم دوبارہ کوشش کریں۔','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'ہلکی سطح تیز ماڈل استعمال کرتی ہے جو اوپر دی گئی ماڈلز ٹیبل میں ترتیب دیا گیا ہے (پہلا: ہائیکو / فلیش)۔ اگر آپ کو اسنپٹ کے لیے مکمل صفحہ کے مترادف ترجمہ کی درستگی چاہیے تو معیار پر سوئچ کریں۔','The phrase as it appears in the source text.'=>'ماخذ متن میں جیسا ظاہر ہوتا ہے۔','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'پہلی زبان ہمیشہ آپ کی سائٹ کے روٹ پر سروس کی جاتی ہے — راستہ موڈ میں URL پیشگی نہیں، سب ڈومین موڈ میں زبان کا سب ڈومین نہیں۔ دیگر زبانیں یا تو /lang/ راستہ پیشگی استعمال کرتی ہیں (مثلاً example.com/de/) یا زبان کا سب ڈومین (مثلاً de.example.com)، جو نیچے دی گئی URL ساخت کی ترتیب پر منحصر ہے۔','The source page has no footnotes.'=>'ماخذ صفحہ میں کوئی نوٹ نہیں ہے۔','The upload failed — please try again.'=>'اپ لوڈ ناکام رہا — براہ کرم دوبارہ کوشش کریں۔','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'یہ نوٹس ماخذ صفحہ سے آتے ہیں اور صرف حوالہ کے لیے یہاں دکھائے جاتے ہیں۔ انہیں اس صفحہ میں شامل کریں۔','This is the source page. Footnotes are edited directly in the block editor.'=>'یہ ماخذ صفحہ ہے۔ نوٹ براہ راست بلاک ایڈیٹر میں ترمیم کیے جاتے ہیں۔','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'یہ کلید فی الحال ایک سرور %s سے فراہم کی جا رہی ہے اور اسے یہاں سے ہٹایا نہیں جا سکتا۔ اسے اوور رائیڈ کرنے کے لیے اوپر ایک نئی کلید درج کریں۔','Tip: to reset a model to the built-in default, clear the field and save.'=>'اشارہ: ایک ماڈل کو بلٹ ان ڈیفالٹ پر ری سیٹ کرنے کے لیے، فیلڈ کو صاف کریں اور محفوظ کریں۔','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'ایک کسٹم انکرپشن خفیہ کا استعمال کرنے کے لیے (جو کہ حاصل شدہ wp_salt قیمت کے بجائے ہے)، اسے wp-config.php میں شامل کریں:','Today'=>'آج','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'پیش رفت، فراہم کنندہ، اور ماڈل کے لحاظ سے ٹوکن استعمال کی مقدار۔ ہر کامیاب AI کال پر ریکارڈ کیا جاتا ہے؛ ٹیسٹ کنکشن پنگز کو جان بوجھ کر خارج کیا گیا ہے تاکہ وہ کل کو متاثر نہ کریں۔ بنیادی جدول روزانہ کا تجزیہ کرتی ہے — اسے دیکھنے کے لیے نیچے ایک ونڈو منتخب کریں۔','Tone'=>'لہجہ','tone'=>'لہجہ','Tone:'=>'لہجہ:','Too many AI requests. Please retry in %d seconds.'=>'بہت زیادہ AI درخواستیں۔ براہ کرم %d سیکنڈ میں دوبارہ کوشش کریں۔','Total'=>'کل','Total tokens'=>'کل ٹوکنز','Translate'=>'ترجمہ کریں','Translate / Revise'=>'ترجمہ / نظر ثانی','Translate / Revise block'=>'بلاک کا ترجمہ / نظر ثانی','Translate all'=>'تمام ترجمہ کریں','Translate chunk'=>'ٹکڑا ترجمہ کریں','Translate Content'=>'مواد کا ترجمہ کریں','Translate missing'=>'غائب ترجمہ کریں','Translate page…'=>'صفحہ ترجمہ کریں…','Translated content'=>'مترجم مواد','Translated Names'=>'ترجمہ شدہ نام','Translated title'=>'مترجم عنوان','Translated to:'=>'ترجمہ شدہ:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'ترجمہ کیا گیا۔ سائٹ ایڈیٹر میں جائزہ لیں — اندرونی روابط، نیویگیشن یو آر ایل، اور ٹیمپلیٹ سلگ خودکار طور پر اپ ڈیٹ نہیں ہوتے۔','Translating…'=>'ترجمہ ہو رہا ہے…','Translation'=>'ترجمہ','Translation Caching'=>'ترجمہ کیشنگ','Translation found but permalink could not be generated'=>'ترجمہ ملا لیکن لنک مستقل لنک تیار نہیں کیا جا سکا','Translation Limits'=>'ترجمہ کی حدیں','Translation Limits & Behavior'=>'ترجمہ کی حدیں اور رویہ','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'ترجمہ کی حدیں: کنٹرول کریں کہ کون سے صارف کے کردار AI ترجمہ کو فعال کرسکتے ہیں، اور ایک ماہانہ ٹوکن بجٹ مقرر کریں۔ بجٹ سے تجاوز کرنے پر AI کالز معطل ہوجائیں گی یہاں تک کہ مہینہ ختم ہو جائے۔','Translation Memory'=>'ترجمہ یادداشت','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'ترجمہ یادداشت AI کے نتائج کو مواد کے ہیش، زبان کے جوڑے، فراہم کنندہ، اور ماڈل کے ذریعے کیش کرتی ہے۔ کسی پوسٹ میں ترمیم کرنے سے کیش انٹری منسوخ ہو جاتی ہے تاکہ اگلی ترجمہ کال تازہ نتیجہ حاصل کرے۔','Translation Memory cleared. %d cached block was removed.'=>'ترجمہ یادداشت صاف کی گئی۔ %d کیش شدہ بلاک ہٹا دیا گیا۔' . "\0" . 'ترجمہ یادداشت صاف کی گئی۔ %d کیش شدہ بلاک ہٹا دیے گئے۔','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'ترجمہ یادداشت: ہر مواد کے ہیش کے مطابق مکمل ترجمہ شدہ پوسٹ کو محفوظ کرتی ہے۔ اسے صاف کریں جب آپ چاہتے ہیں کہ تمام پوسٹس کا دوبارہ ترجمہ زبردستی کیا جائے، چاہے ان کا مواد تبدیل ہوا ہو یا نہ ہوا ہو۔','Translation workflow'=>'ترجمہ کا ورک فلو','Translation, Content Generator'=>'ترجمہ، مواد تخلیق','Type'=>'قسم','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'رویے ان انسٹال کریں','Uninstall setting saved.'=>'ان انسٹال سیٹنگ محفوظ کی گئی۔','unknown error'=>'نامعلوم غلطی','Unknown provider.'=>'نامعلوم فراہم کنندہ۔','Up'=>'اوپر','Upload .mo file'=>'.mo فائل اپ لوڈ کریں','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'تیسری پارٹی پلگ ان کے اسٹرنگز کو اوور رائڈ کرنے کے لیے مرتب شدہ .mo فائلیں اپ لوڈ کریں — مثال کے طور پر، ایک کسٹم ویک بُکنگ ترجمہ جو "کمرہ" کے بجائے "اپارٹمنٹ" استعمال کرتا ہے۔ فائلیں ورڈپریس کے نام کی قاعدہ کی پیروی کرتی ہیں: {textdomain}-{locale}.mo (مثلاً vikbooking-ca.mo)۔ یہ اپ لوڈز فولڈر میں محفوظ ہوتی ہیں اور پلگ ان اپ ڈیٹس کے دوران برقرار رہتی ہیں۔','Upload Override'=>'اوور رائڈ اپ لوڈ کریں','URL could not be mapped to a post — check the link target exists'=>'URL کو پوسٹ سے منسلک نہیں کیا جا سکا — چیک کریں کہ لنک کا ہدف موجود ہے','URL structure'=>'URL ساخت','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL کا ڈھانچہ: پاتھ-پری فکس موڈ (مثلاً.com/de/) کسی سرور تبدیلی کے بغیر کام کرتا ہے۔ سب ڈومین موڈ (de.example.com) کے لیے ایک وائلڈ کارڈ DNS ریکارڈ، وائلڈ کارڈ SSL سرٹیفکیٹ، اور ویب سرور کنفیگریشن میں تبدیلی کی ضرورت ہوتی ہے — سرور سیٹ اپ گائیڈ دیکھیں۔','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'اس صفحہ کے اوپر ٹیبز کا استعمال کریں تاکہ ہر علاقے کو ترتیب دیا جا سکے۔ روٹر ٹیب میں تبدیلیاں فوری اثر انداز ہوتی ہیں؛ AI کیز اور ماڈل سیٹنگز میں تبدیلیاں اگلی AI درخواست پر لاگو ہوتی ہیں۔','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'زبان کے جوڑے کے مطابق صارف کے زیر انتظام اصطلاحات کی جدول۔ اندراجات ترجمہ نظام کے اشارے میں شامل کی جاتی ہیں تاکہ AI ترجیحی اصطلاحات کو مستقل استعمال کرے — شعبہ جاتی الفاظ ("kWp", "PPA", "interconnection point")، برانڈ کے نام جو ترجمہ نہیں ہونے چاہئیں، اور معیاری ضابطہ بندی کے جملے کے لیے اہم۔ دونوں زبان کے فیلڈز اختیاری ہیں: "ماخذ زبان" کو خالی چھوڑیں تاکہ یہ اندراج کسی بھی زبان سے ترجمہ کرنے کے باوجود لاگو ہو؛ "ہدف زبان" کو خالی چھوڑیں تاکہ یہ تمام ہدف زبانوں پر ایک ساتھ لاگو ہو۔','Using custom meta description.'=>'کاستم میٹا تفصیل استعمال کر رہے ہیں۔','View'=>'دیکھیں','View built-in default'=>'بلٹ ان ڈیفالٹ دیکھیں','View details'=>'تفصیلات دیکھیں','View Lingua Forge details'=>'لینگوا فورج کی تفصیلات دیکھیں','Visit plugin site'=>'پلگ ان کی سائٹ پر جائیں','Warning:'=>'خبردار:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'جب ڈیبگ لاگنگ فعال ہوتی ہے (نیچے ٹوگل کے ذریعے یا wp-config.php میں LINGUAFORGE_AI_DEBUG کو ڈیفائن کرکے)، ترجمہ اور ایف ایس ای ٹیمپلیٹ ترجمہ خصوصیات اپنی خام اے آئی پرامپٹس اور جوابات کو دشواری حل کے لیے ڈسک پر لکھتی ہیں۔ اس سیکشن کا استعمال اس آؤٹ پٹ کی نگرانی کے لیے کریں اور اسے صاف کریں جب آپ کو ضرورت ہو — فائلیں بڑے صفحات پر تیزی سے بڑھ سکتی ہیں۔ ہدف ڈائریکٹری کو linguaforge_debug_dir فلٹر کے ذریعے ترتیب دیں۔','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'جب فعال ہو، تو پہلی بار آنے والے زائرین جن کے پاس زبان کا کوکی نہیں اور URL میں زبان کا پیش لفظ نہیں، سب سے قریب ملنے والی زبان کے ورژن پر ری ڈائریکٹ کیے جاتے ہیں۔ اگر براؤزر کی ترجیحی زبان فعال روٹر زبانوں میں شامل نہیں ہے، تو ری ڈائریکٹ کو چھوڑ دیا جاتا ہے۔ جب کوئی زائرین سوئچر کے ذریعے زبان منتخب کرتا ہے، تو کوکی ترجیح حاصل کرتی ہے اور براؤزر ہیڈر کو مستقبل کے دوروں پر نظر انداز کیا جاتا ہے۔','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'مکمل صفحہ ترجمہ کے لیے کون سا ماڈل استعمال کرنا ہے۔ معیار اوپر دی گئی ماڈلز ٹیبل میں ترتیب دیا گیا ماڈل استعمال کرتا ہے اور درست، طویل شکل کے ترجمہ کے لیے تجویز کیا جاتا ہے۔ صرف رفتار یا لاگت کو ترجیح دینے اور مواد مختصر ہونے کی صورت میں Light پر سوئچ کریں۔','WP-CLI reference'=>'WP-CLI حوالہ','Write AI prompts and responses to disk for troubleshooting'=>'مسئلے حل کے لیے اے آئی پرامپٹس اور جوابات کو ڈسک پر لکھیں','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'آپ کلیدوں کو مستقل یا ماحولیاتی متغیر کے طور پر بھی تعریف کر سکتے ہیں (مثلاً wp-config.php میں)۔ یہ ذرائع خودکار طور پر استعمال ہوتے ہیں جب کوئی ڈیٹا بیس کلید محفوظ نہیں ہوتی۔','You do not have permission to manage these settings.'=>'آپ کو ان سیٹنگز کو منظم کرنے کی اجازت نہیں ہے۔','You do not have permission to read this post.'=>'آپ کو اس پوسٹ کو پڑھنے کی اجازت نہیں ہے۔','{n} stale path(s)'=>'{n} پرانی راہ/راہیں','— Any source language —'=>'— کوئی بھی ماخذ زبان —','— Any target language —'=>'— کوئی بھی ہدف زبان —','— Any target —'=>'— کوئی بھی ہدف —','— Any —'=>'— کوئی بھی —','— auto-detect —'=>'— خودکار شناخت —','— select a language —'=>'— ایک زبان منتخب کریں —','— toggle in Settings → Behavior.'=>'— سیٹنگز → رویہ میں ٹوگل۔','← Back'=>'← واپس','↑ Detected from current post'=>'↑ موجودہ پوسٹ سے معلوم ہوا','↺ Re-translate'=>'↺ دوبارہ ترجمہ','↺ Refine'=>'↺ بہتر بنائیں','↺ Refresh'=>'↺ تازہ کریں','↺ Refreshing…'=>'↺ تازہ کاری ہو رہی ہے…','⚠ Borderline'=>'⚠ حد سے زیادہ قریب','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ کوئی <strong>{lang}</strong> پوسٹس نہیں ملی۔ یقینی بنائیں کہ تمام ترجمہ شدہ پوسٹس میں زبان کا میٹا <strong>{lang}</strong> پر سیٹ ہے۔','⚠ No changes'=>'⚠ کوئی تبدیلی نہیں','⚠ No changes — re-scan?'=>'⚠ کوئی تبدیلی نہیں — دوبارہ اسکین کریں؟','✅ Fixed ({n})'=>'✅ ٹھیک کیا ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong> کے لیے کوئی ٹوٹے ہوئے لنکس یا ٹیمپلیٹ میں غلطیاں نہیں پائی گئیں۔ <strong>{scanned}</strong> پوسٹ/صفحات اسکین کی گئیں — تمام چیک پاس ہو گئے۔ ٹیمپلیٹ پارٹس کے لنکس (ہیڈر، فوٹر، سائیڈبار) یہاں شامل نہیں ہیں — ان کو علیحدہ سے چیک کرنے کے لیے فکس ٹیمپلیٹ پارٹس بٹن استعمال کریں۔','✅ Template fixed'=>'✅ ٹیمپلیٹ درست ہو گیا','✓ All parts created.'=>'✓ تمام حصے بن گئے۔','✓ All templates created.'=>'✓ تمام ٹیمپلیٹس بن گئے۔','✓ All translated.'=>'✓ سب ترجمہ ہو گیا۔','✓ Configured'=>'✓ ترتیب دیا گیا','✓ Connection OK'=>'✓ کنکشن ٹھیک ہے','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ مواد تیار — جائزہ لینے، بہتر بنانے، اور لاگو کرنے کے لیے اوورلے دیکھیں۔','✓ Done'=>'✓ مکمل','✓ Enabled'=>'✓ فعال','✓ Good length'=>'✓ اچھا طول','✓ In safe storage'=>'✓ محفوظ اسٹوریج میں','✓ Language installed.'=>'✓ زبان انسٹال ہو گئی ہے۔','✓ Links fixed.'=>'✓ روابط درست ہو گئے۔','✓ Nav refs fixed.'=>'✓ نیویگیشن ریفرنسز درست۔','✓ Parts fixed.'=>'✓ حصے درست ہو گئے۔','✓ Pattern translated.'=>'✓ پیٹرن ترجمہ ہو گیا۔','✓ Refined — review the updated draft above.'=>'✓ ترمیم شدہ — اوپر دی گئی مسودہ کا جائزہ لیں۔','✓ Translation saved'=>'✓ ترجمہ محفوظ ہو گیا','✗ Disabled'=>'✗ غیر فعال','✗ Error:'=>'✗ خرابی:','✗ Failed:'=>'✗ ناکام:','✗ Not configured'=>'✗ ترتیب نہیں دیا گیا','✗ Too long'=>'✗ بہت لمبا','✗ Too short'=>'✗ بہت چھوٹا','❌ Failed'=>'❌ ناکام','📄 Wrong template'=>'📄 غلط ٹیمپلیٹ','📍 Stale path (page moved)'=>'📍 پرانی راہ (صفحہ منتقل ہو گیا)']];
